import { S3Client } from '@aws-sdk/client-s3';
import { S3Storage } from './storage.ts';
import { ClamdScanner } from './scanner.ts';
import { FileError } from './errors.ts';

export interface FileInfrastructureConfiguration {
  endpoint: string; region: string; bucket: string; accessKeyId: string; secretAccessKey: string;
  scannerHost: string; scannerPort: number;
}
/** Caller supplies trusted configuration; no environment files are read or generated by the module. */
export function createFileInfrastructure(configuration: FileInfrastructureConfiguration) {
  let endpoint: URL;
  try { endpoint = new URL(configuration.endpoint); } catch { throw new FileError('SERVICE_UNAVAILABLE'); }
  if (!['https:', 'http:'].includes(endpoint.protocol) || endpoint.username || endpoint.password || endpoint.search || endpoint.hash
    || endpoint.pathname !== '/' || (endpoint.protocol === 'http:' && !['127.0.0.1', 'localhost', '[::1]'].includes(endpoint.hostname))
    || !/^[a-z0-9-]{1,64}$/.test(configuration.region)
    || !/^[a-zA-Z0-9]{16,128}$/.test(configuration.accessKeyId)
    || typeof configuration.secretAccessKey !== 'string' || configuration.secretAccessKey.length < 32
    || configuration.secretAccessKey.length > 256 || /[\u0000-\u001f\u007f]/.test(configuration.secretAccessKey)
    || !['127.0.0.1', 'localhost', '::1'].includes(configuration.scannerHost)) throw new FileError('SERVICE_UNAVAILABLE');
  const client = new S3Client({ endpoint: endpoint.href, region: configuration.region,
    credentials: { accessKeyId: configuration.accessKeyId, secretAccessKey: configuration.secretAccessKey },
    forcePathStyle: true, maxAttempts: 1, requestChecksumCalculation: 'WHEN_REQUIRED', responseChecksumValidation: 'WHEN_REQUIRED' });
  try {
    const storage = new S3Storage(client, configuration.bucket);
    const scanner = new ClamdScanner(configuration.scannerHost, configuration.scannerPort);
    return { storage, scanner, close: () => client.destroy() };
  } catch { client.destroy(); throw new FileError('SERVICE_UNAVAILABLE'); }
}
